import { useMemo, useState } from 'react';

type InputProps = {
  options: string[];
  validate?: (value: string) => boolean;
  onChange?: (value: string) => void;
};

export function Input({ options, validate, onChange }: InputProps) {
  const [value, setValue] = useState('');
  const [focused, setFocused] = useState(false);

  const matches = useMemo(() => {
    const query = value.trim().toLocaleLowerCase();
    return query
      ? options.filter(option => option.toLocaleLowerCase().includes(query))
      : [];
  }, [options, value]);

  const isValid = !value || (validate ? validate(value) : true);

  function updateValue(next: string) {
    setValue(next);
    onChange?.(next);
  }

  return (
    <div>
      <input
        value={value}
        onChange={event => updateValue(event.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        aria-invalid={!isValid}
        style={{ border: `1px solid ${isValid ? '#ccc' : 'red'}` }}
      />
      {focused && matches.length > 0 && (
        <ul>
          {matches.map(option => (
            <li key={option} onMouseDown={() => updateValue(option)}>
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

For very large lists, the `<li>` rendering should be replaced with a virtualized list (for example, `react-window`) so only visible suggestions are mounted.

