import { useEffect, useMemo, useRef, useState } from 'react';

type InputProps = {
  options: string[];
  value?: string;
  onChange?: (value: string) => void;
  validate?: (value: string) => boolean;
  placeholder?: string;
};

export function Input({
  options,
  value,
  onChange,
  validate,
  placeholder,
}: InputProps) {
  const [internalValue, setInternalValue] = useState('');
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);

  const inputValue = value ?? internalValue;
  const valid = validate ? validate(inputValue) : true;

  const matches = useMemo(() => {
    const query = inputValue.trim().toLowerCase();
    return query
      ? options.filter(option => option.toLowerCase().includes(query))
      : [];
  }, [inputValue, options]);

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
        setActiveIndex(-1);
      }
    };

    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const updateValue = (nextValue: string) => {
    if (value === undefined) setInternalValue(nextValue);
    onChange?.(nextValue);
  };

  const choose = (option: string) => {
    updateValue(option);
    setOpen(false);
    setActiveIndex(-1);
  };

  return (
    <div ref={containerRef} style={{ position: 'relative' }}>
      <input
        value={inputValue}
        placeholder={placeholder}
        onChange={event => {
          updateValue(event.target.value);
          setOpen(true);
          setActiveIndex(-1);
        }}
        onFocus={() => setOpen(true)}
        onKeyDown={event => {
          if (event.key === 'Escape') setOpen(false);
          if (!matches.length) return;

          if (event.key === 'ArrowDown') {
            event.preventDefault();
            setActiveIndex(index => (index + 1) % matches.length);
          } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setActiveIndex(index => (index - 1 + matches.length) % matches.length);
          } else if (event.key === 'Enter' && activeIndex >= 0) {
            event.preventDefault();
            choose(matches[activeIndex]);
          }
        }}
        aria-autocomplete="list"
        aria-expanded={open && matches.length > 0}
        style={{ border: `1px solid ${valid ? '#888' : 'red'}` }}
      />

      {open && matches.length > 0 && (
        <ul
          role="listbox"
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            maxHeight: 200,
            overflowY: 'auto',
            margin: 0,
            padding: 0,
            background: 'white',
            listStyle: 'none',
            zIndex: 1,
          }}
        >
          {matches.map((option, index) => (
            <li
              key={`${option}-${index}`}
              role="option"
              aria-selected={index === activeIndex}
              onMouseDown={event => event.preventDefault()}
              onClick={() => choose(option)}
              style={{
                padding: 8,
                cursor: 'pointer',
                background: index === activeIndex ? '#eee' : 'white',
              }}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

For exceptionally large lists, replace the `<li>` mapping with a virtualized list (for example, `react-window`); `useMemo` avoids recalculating the filter unless the input or options change, but it does not itself prevent rendering every match.

### Evaluation

**Assistant B is much better.** It gives a mostly coherent React/TypeScript implementation with filtering, a validator, keyboard navigation, and a usage example. Its filtering makes the dropdown disappear when there are no matches. However, some behavior it claims is incomplete: outside clicks and Escape only reset `activeIndex`, while dropdown visibility depends on `filteredOptions.length`, so the dropdown may remain visible. It also does not synchronize its internal state with later changes to the `value` prop, and validation is not recalculated on selection or initial prop changes. Despite using `useMemo`, it renders every match, so it does not fully address very large option lists; virtualization is only suggested.

